// ===== CONFIG (edit here) =====
const CONFIG = {
  alertEmail: 'you@example.com',
  criticalWorkflows: /invoice|payment|finance|stripe|billing|onboarding|lead|support/i,
  transient: /429|rate.?limit|timeout|timed out|ETIMEDOUT|ECONNRESET|ECONNREFUSED|socket hang up|\b50[234]\b|temporar|overloaded/i,
  auth: /\b401\b|\b403\b|unauthori[sz]ed|forbidden|invalid.*(token|credential|api.?key)|expired|permission|not authori[sz]ed/i,
};
const item = $input.first().json || {};
const ex = item.execution || {};
const trig = item.trigger || {};
const wf = item.workflow || {};
const err = ex.error || trig.error || {};
const message = String(err.message || 'Unknown error').slice(0, 1000);
const failedNode = (err.node && err.node.name) || ex.lastNodeExecuted || 'unknown';
const isTriggerFailure = !!trig.error; // the trigger itself failed (not just a run that was started by a trigger)
const mode = isTriggerFailure ? 'trigger-failure' : (ex.mode || 'execution');
const workflowName = wf.name || 'unknown workflow';

let errorClass = 'unknown';
if (CONFIG.auth.test(message)) errorClass = 'auth';
else if (CONFIG.transient.test(message)) errorClass = 'transient';
else if (/validation|invalid|required|missing|schema|parse|JSON/i.test(message)) errorClass = 'data';

let severity = 'high';
if (errorClass === 'transient') severity = 'medium';
if (CONFIG.criticalWorkflows.test(workflowName) && errorClass !== 'transient') severity = 'critical';
if (isTriggerFailure) severity = 'critical'; // a dead trigger means the workflow is not listening at all

const executionId = String(ex.id || '');
const fingerprint = workflowName + '|' + failedNode + '|' + message.slice(0, 120);
const stack = String(err.stack || '').slice(0, 1500);
const payload = JSON.stringify({
  workflow_id: wf.id || null, failed_node: failedNode, error_class: errorClass, mode,
  execution_url: ex.url || null, retry_of: ex.retryOf || null, stack, error: err,
}).slice(0, 8000);

return [{ json: {
  event_type: 'error',
  source_workflow: workflowName,
  workflow_id: wf.id || '',
  failed_node: failedNode,
  error_message: message,
  error_class: errorClass,
  severity,
  mode,
  timestamp: $now.toISO(),
  execution_id: executionId,
  execution_url: ex.url || '',
  fingerprint,
  stack,
  payload_json: payload,
  channel: 'n8n',
  alert_email: CONFIG.alertEmail,
} }];

// Always keep the audit row (written upstream). Only de-duplicate the ALERTS, so an error storm cannot flood Slack/email.
const j = $('Normalize & Classify').first().json;
const auditFailed = !!(($input.first() || {}).json && $input.first().json.error);
const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};
const now = Date.now();
const WINDOW_MS = 15 * 60 * 1000;      // identical error: alert at most once per 15 minutes
const KEEP_MS = 6 * 60 * 60 * 1000;    // forget fingerprints after 6 hours
for (const k of Object.keys(store.seen)) { if (now - store.seen[k].t > KEEP_MS) delete store.seen[k]; }
const prev = store.seen[j.fingerprint];
let shouldAlert = true; let suppressed = 0;
if (prev && now - prev.t < WINDOW_MS) { prev.count = (prev.count || 1) + 1; shouldAlert = false; }
else { suppressed = prev ? Math.max((prev.count || 1) - 1, 0) : 0; store.seen[j.fingerprint] = { t: now, count: 1 }; }
return [{ json: { ...j, audit_failed: auditFailed, should_alert: shouldAlert, suppressed_since_last: suppressed } }];

