const j = $('Throttle & Decide').first().json;
const ai = ($json && $json.output && typeof $json.output === 'object') ? $json.output : null;
const icon = { critical: ':rotating_light:', high: ':warning:', medium: ':large_yellow_circle:' }[j.severity] || ':warning:';
const L = [];
L.push(icon + ' *' + j.severity.toUpperCase() + ' workflow error*');
L.push('*Workflow:* ' + j.source_workflow);
L.push('*Failed node:* ' + j.failed_node + '   *Class:* ' + j.error_class + '   *Mode:* ' + j.mode);
L.push('*Error:* ' + j.error_message);
L.push('*Time:* ' + j.timestamp);
if (j.execution_url) L.push('*Execution:* ' + j.execution_url);
if (j.suppressed_since_last > 0) L.push('_' + j.suppressed_since_last + ' identical error(s) suppressed since the last alert_');
if (j.audit_failed) L.push(':no_entry: *Audit row could NOT be written, check the data table*');
if (ai) {
  L.push('');
  L.push('*AI triage* (confidence: ' + ai.confidence + ')');
  L.push('*Likely cause:* ' + ai.likely_cause);
  L.push('*First fix to try:* ' + ai.first_fix);
  L.push('*Safe to retry:* ' + (ai.retry_safe ? 'yes' : 'no') + '   *Impact:* ' + ai.business_impact);
}
const slackText = L.join('\n');
const emailBody = slackText.replace(/\*/g, '').replace(/_/g, '').replace(/:[a-z_]+:/g, '').trim() + '\n\nThe full payload is stored as a dead-letter record in the audit table.';
return [{ json: { ...j, slack_text: slackText, email_subject: '[' + j.severity.toUpperCase() + '] n8n error: ' + j.source_workflow + ' / ' + j.failed_node, email_body: emailBody, send_email: (j.severity === 'critical' || j.severity === 'high') } }];
